import { rollup, type OutputAsset } from "rollup";
import path from "path";
import uiPage from "../../src/ui-page";
import sass from "../../src/sass";
import { cssUrl } from "../../src/css-url";
import swc from "../../src/swc";
import nodeResolve from "../../src/node-resolve";
import uiPageSourceManifest from "../../src/ui-page-source-manifest";
import type { UiPageSourceManifest } from "../../src/ui-page-source-manifest";

/**
 * Integration tests that compose the source manifest plugin with
 * real rollup plugins used in BYOUI builds:
 *
 *   uiPage          — extracts <script src> from HTML, emits HTML assets
 *   cssUrl          — resolves url() refs in CSS/SCSS to inlined or extracted assets
 *   sass            — compiles SCSS, injects $insertStyle virtual module
 *   swc             — transpiles TypeScript/JSX
 *   nodeResolve     — resolves bare-specifier imports
 *
 * These tests use on-disk fixture files in ./fixtures/ to exercise
 * the full plugin pipeline end-to-end.
 */

const FIXTURES = path.resolve(__dirname, "fixtures");
const ROOT_DIR = FIXTURES;
const CLIENT_DIR = path.join(FIXTURES, "src/client");

/** Run a real build with the BYOUI plugin stack. */
const build = async (htmlGlob: string) => {
  const bundle = await rollup({
    input: htmlGlob,
    plugins: [
      uiPage({ rootDir: ROOT_DIR }),
      cssUrl(),
      sass({ insert: true }),
      nodeResolve({
        preferBuiltins: false,
        browser: true,
        extensions: [".ts", ".tsx", ".js", ".jsx"],
      }),
      swc({
        swc: {
          jsc: {
            parser: { tsx: true, syntax: "typescript" },
            transform: { react: { runtime: "automatic" } },
          },
        },
      }),
      uiPageSourceManifest({ rootDir: ROOT_DIR, clientDir: CLIENT_DIR }),
    ],
    onwarn(warning, handler) {
      // Suppress warnings that are expected in test builds
      if (
        warning.code === "UNRESOLVED_IMPORT" ||
        warning.code === "CIRCULAR_DEPENDENCY"
      )
        return;
      handler(warning);
    },
  });

  const { output } = await bundle.generate({ format: "es" });
  await bundle.close();
  return output;
};

const getManifest = (
  output: Awaited<ReturnType<typeof build>>,
  fileName: string,
): UiPageSourceManifest => {
  const asset = output.find(
    (o) => o.type === "asset" && o.fileName === fileName,
  ) as OutputAsset | undefined;
  if (!asset) {
    throw new Error(
      `Manifest ${fileName} not found. Assets: ${output
        .filter((o) => o.type === "asset")
        .map((o) => o.fileName)
        .join(", ")}`,
    );
  }
  return JSON.parse(asset.source as string);
};

// ── Tests ────────────────────────────────────────────────────────

describe("Source Manifest with real plugins", () => {
  test("generates manifest with uiPage + sass + swc pipeline", async () => {
    const output = await build(path.join(CLIENT_DIR, "index.html"));

    const m = getManifest(output, "src/client/index.ui-source-manifest.json");

    // Entry is set correctly
    expect(m.entry).toBe("src/client/app.tsx");

    // Source .tsx files are included
    expect(m.files).toContainEqual(expect.stringContaining("app.tsx"));
    expect(m.files).toContainEqual(expect.stringContaining("Button.tsx"));

    // SCSS source files are included (not filtered)
    expect(m.files).toContainEqual(expect.stringContaining("app.scss"));
    expect(m.files).toContainEqual(expect.stringContaining("Button.scss"));

    // $insertStyle virtual module is filtered out
    expect(m.files).not.toContainEqual(expect.stringContaining("$insertStyle"));
    expect(m.files).not.toContainEqual(expect.stringMatching(/___/));
  });

  test("includes CSS url() assets in manifest via css-url plugin", async () => {
    const output = await build(path.join(CLIENT_DIR, "index.html"));

    const m = getManifest(output, "src/client/index.ui-source-manifest.json");

    // Button.scss references logo.png (image) and icon.svg via url()
    expect(m.files).toContainEqual(expect.stringContaining("assets/logo.png"));
    expect(m.files).toContainEqual(expect.stringContaining("assets/icon.svg"));

    // app.scss references font.woff2 via @font-face url()
    expect(m.files).toContainEqual(
      expect.stringContaining("assets/font.woff2"),
    );
  });

  test("does not include node_modules in manifest", async () => {
    const output = await build(path.join(CLIENT_DIR, "index.html"));

    const m = getManifest(output, "src/client/index.ui-source-manifest.json");

    expect(m.files).not.toContainEqual(expect.stringContaining("node_modules"));
  });

  test("manifest files are sorted", async () => {
    const output = await build(path.join(CLIENT_DIR, "index.html"));

    const m = getManifest(output, "src/client/index.ui-source-manifest.json");
    const sorted = [...m.files].sort();
    expect(m.files).toEqual(sorted);
  });
});
